using System;
using System.Collections.Generic;
using UnityEngine;

namespace DontForgetMe
{
    // Generated by "Dont Forget Me/Rebuild Art Library". Holds every imported asset the
    // procedural world needs, so player builds include them without scene references.
    public sealed class ArtCatalog : ScriptableObject
    {
        [Serializable]
        public struct Entry
        {
            public string id;
            public UnityEngine.Object asset;
            // Surfaces: real-world size in metres covered by one texture repeat.
            // Props: bounding box size, with the box centre relative to the pivot in "center".
            public Vector3 size;
            public Vector3 center;
        }

        public List<Entry> entries = new List<Entry>();
        public float[] ambient = new float[27];
    }
}
